const body = $json.body ?? $json;
const eventName = body.pull_request ? (body.review ? 'pull_request_review' : 'pull_request') : (body.comment ? 'issue_comment' : (body.ref ? 'push' : 'unknown'));
let deploy_signal = 'ignore';
if (eventName === 'pull_request' && body.action === 'labeled' && body.label?.name === 'ready-to-deploy') deploy_signal = 'label_ready_to_deploy';
else if (eventName === 'pull_request_review' && String(body.review?.state || '').toLowerCase() === 'approved') deploy_signal = 'review_approved';
else if (eventName === 'issue_comment' && /^\/deploy-lab\b/i.test(body.comment?.body || '')) deploy_signal = 'manual_deploy_comment';
else if (eventName === 'push' && /refs\/heads\/main$/i.test(body.ref || '')) deploy_signal = 'merge_to_main';
const repo = body.repository || {};
const owner = repo.owner?.login || repo.owner?.name || (repo.full_name || '').split('/')[0] || 'abdul4rehman215';
const repoName = repo.name || (repo.full_name || 'wazuh-genai-ci').split('/').pop();
const prNumber = Number(body.pull_request?.number || body.issue?.number || 0);
return [{json:{
  event_name: eventName,
  event_action: body.action || '',
  deploy_signal,
  owner,
  repo_name: repoName,
  repo: repo.full_name || `${owner}/${repoName}`,
  pr_number: prNumber,
  issue_number: prNumber,
  review_state: body.review?.state || '',
  comment_body: body.comment?.body || '',
  actor: body.sender?.login || 'github',
  head_sha: body.pull_request?.head?.sha || body.after || '',
  base_sha: body.pull_request?.base?.sha || '',
  base_ref: body.pull_request?.base?.ref || 'main',
  received_at: new Date().toISOString()
}}];

const c = $json.deploy_context;
const missing = c.required_labels.filter(x => !c.labels.includes(x));
const allowed = missing.length === 0 && c.approved === true && c.deploy_signal_ok === true;
const parts = [];
if (missing.length) parts.push(`missing=${missing.join(',')}`);
if (!c.approved) parts.push('approval=false');
if (!c.deploy_signal_ok) parts.push(`signal=${c.deploy_signal}`);
return [{ json: { ...$json, deploy_allowed: allowed, missing_labels: missing, gate_reason: allowed ? 'gate_passed' : `blocked ${parts.join(' ')}` } }];

const ctx = $('Code_Check_B2_Deploy_Gate').first().json;
const rawOut = String($json.stdout || $json.data || '');
const rawErr = String($json.stderr || $json.error || '');
let result = null;
try {
  result = JSON.parse(rawOut || '{}');
} catch (e1) {
  try {
    const start = rawOut.indexOf('{');
    const end = rawOut.lastIndexOf('}');
    result = start >= 0 && end > start ? JSON.parse(rawOut.slice(start, end + 1)) : null;
  } catch (e2) {
    result = null;
  }
}
if (!result || typeof result !== 'object') {
  result = {
    decision: 'fail',
    deployment_status: 'failed',
    error: rawErr || rawOut || 'Flow B2 local deploy command did not return parseable JSON',
    stdout: rawOut,
    stderr: rawErr
  };
}
return [{ json: { ...ctx, deploy_result: result, deploy_decision: result.decision || 'fail', deployment_status: result.deployment_status || 'unknown' } }];

function esc(v) { return String(v ?? '').replace(/\|/g, '\\|'); }
function arr(v) { return Array.isArray(v) ? v : []; }
function pick(...vals) { for (const v of vals) if (v !== undefined && v !== null && v !== '') return v; return ''; }
const c = $json.deploy_context || {};
const r = $json.deploy_result || {};
const now = new Date().toISOString();
const stages = arr(r.stages || r.stage_results || r.stage_results_json);
const stageRows = stages.map(s => ({
  stage_name: s.stage_name || s.stage || s.name || 'unknown',
  status: s.status || (s.passed === true ? 'pass' : s.passed === false ? 'fail' : 'unknown'),
  passed: s.passed === true || s.status === 'pass',
  summary: s.summary || s.detail || s.error || ''
}));
const passed = stageRows.filter(s => s.passed).length;
const failed = stageRows.length ? stageRows.length - passed : (String(r.decision || '').toLowerCase() === 'pass' ? 0 : 1);
const decision = String(pick(r.decision, $json.deploy_decision, 'fail')).toLowerCase();
const status = String(pick(r.deployment_status, r.deployment_run_row?.deployment_status, decision === 'pass' ? 'deployed' : 'failed')).toLowerCase();
const existingRun = r.deployment_run_row || {};
const existingBundle = r.policy_bundle_deployment_row || {};
const deploymentRunId = pick(existingRun.deployment_run_id, c.deployment_id, `flow-b2-${String(c.repo || 'repo').replace('/','-')}-pr-${c.pr_number || 'na'}-${Date.now()}`);
const labels = arr(r.labels).length ? arr(r.labels) : arr(c.labels);
const deploymentRunRow = {
  deployment_run_id: deploymentRunId,
  timestamp: pick(existingRun.timestamp, existingRun.started_at, now),
  deployment_mode: pick(existingRun.deployment_mode, c.deploy_mode, 'execute'),
  deployment_status: pick(existingRun.deployment_status, status),
  repo: pick(existingRun.repo, c.repo),
  pr_number: Number(pick(existingRun.pr_number, c.pr_number, 0)),
  commit_sha: pick(existingRun.commit_sha, c.commit_sha),
  actor: pick(existingRun.actor, c.actor),
  approved: Boolean(pick(existingRun.approved, c.approved, false)),
  gate_passed: existingRun.gate_passed === undefined ? true : Boolean(existingRun.gate_passed),
  required_labels_csv: pick(existingRun.required_labels_csv, arr(c.required_labels).join(',')),
  observed_labels_csv: pick(existingRun.observed_labels_csv, labels.join(',')),
  backup_root: pick(existingRun.backup_root, r.backup_root),
  wazuh_backup_path: pick(existingRun.wazuh_backup_path, r.wazuh_backup_path, r.backup_path),
  policy_backup_path: pick(existingRun.policy_backup_path, r.policy_backup_path),
  staging_dir: pick(existingRun.staging_dir, r.staging_dir, r.stage_dir),
  wazuh_rules_count: Number(pick(existingRun.wazuh_rules_count, r.wazuh_rules_count, 0)),
  wazuh_decoders_count: Number(pick(existingRun.wazuh_decoders_count, r.wazuh_decoders_count, 0)),
  policy_files_count: Number(pick(existingRun.policy_files_count, r.policy_files_count, existingBundle.policy_files_count, 0)),
  predeploy_status: pick(existingRun.predeploy_status, r.predeploy_status, stageRows.find(s => /predeploy|xml|smoke/i.test(s.stage_name))?.status, ''),
  postdeploy_status: pick(existingRun.postdeploy_status, r.postdeploy_status, stageRows.find(s => /postdeploy/i.test(s.stage_name))?.status, ''),
  rollback_performed: Boolean(pick(existingRun.rollback_performed, r.rollback_performed, false)),
  rollback_reason: pick(existingRun.rollback_reason, r.rollback_reason),
  slack_notified: Boolean(existingRun.slack_notified || false),
  github_comment_posted: Boolean(existingRun.github_comment_posted || false),
  error: pick(existingRun.error, r.error, r.parse_error),
  stage_results_json: pick(existingRun.stage_results_json, JSON.stringify(stageRows)),
  notes: pick(existingRun.notes, r.notes, r.slack_summary, `Flow B2 deployment ${decision}`)
};
const policyBundleRow = {
  policy_deployment_id: pick(existingBundle.policy_deployment_id, `${deploymentRunId}:policy-bundle`),
  timestamp: pick(existingBundle.timestamp, deploymentRunRow.timestamp, now),
  deployment_run_id: pick(existingBundle.deployment_run_id, deploymentRunId),
  repo: pick(existingBundle.repo, c.repo),
  commit_sha: pick(existingBundle.commit_sha, c.commit_sha),
  actor: pick(existingBundle.actor, c.actor),
  policy_bundle_version: pick(existingBundle.policy_bundle_version, r.policy_bundle_version, 'v2-policy-bundle'),
  policy_bundle_hash: pick(existingBundle.policy_bundle_hash, r.policy_bundle_hash, ''),
  mcp_policy_files_count: Number(pick(existingBundle.mcp_policy_files_count, r.mcp_policy_files_count, 0)),
  rag_memory_policy_files_count: Number(pick(existingBundle.rag_memory_policy_files_count, r.rag_memory_policy_files_count, 0)),
  agentic_policy_files_count: Number(pick(existingBundle.agentic_policy_files_count, r.agentic_policy_files_count, 0)),
  policy_target_dir: pick(existingBundle.policy_target_dir, r.policy_target_dir, ''),
  policy_backup_path: pick(existingBundle.policy_backup_path, deploymentRunRow.policy_backup_path),
  policy_staging_path: pick(existingBundle.policy_staging_path, r.policy_staging_path, deploymentRunRow.staging_dir),
  deployment_status: pick(existingBundle.deployment_status, deploymentRunRow.deployment_status),
  rollback_performed: Boolean(pick(existingBundle.rollback_performed, deploymentRunRow.rollback_performed, false)),
  active_mcp_bundle_hash: pick(existingBundle.active_mcp_bundle_hash, r.active_mcp_bundle_hash, ''),
  active_rag_memory_bundle_hash: pick(existingBundle.active_rag_memory_bundle_hash, r.active_rag_memory_bundle_hash, ''),
  active_agentic_bundle_hash: pick(existingBundle.active_agentic_bundle_hash, r.active_agentic_bundle_hash, ''),
  postdeploy_validation_status: pick(existingBundle.postdeploy_validation_status, deploymentRunRow.postdeploy_status),
  error: pick(existingBundle.error, deploymentRunRow.error),
  notes: pick(existingBundle.notes, 'Flow B2 policy bundle deployment row')
};
const title = decision === 'pass' ? 'Flow B2 Controlled Wazuh + AI Security Policy Deployment' : 'Flow B2 Controlled Wazuh + AI Security Policy Deployment FAILED';
const stageMd = stageRows.length ? stageRows.map(s => `- ${s.passed ? 'PASS' : 'FAIL'} ${s.stage_name}: ${s.status}${s.summary ? ` - ${s.summary}` : ''}`).join('\n') : '- No stage rows returned by deploy script';
const githubBody = `## ${title}\n\n**Decision:** ${decision.toUpperCase()}  \n**Deployment status:** ${deploymentRunRow.deployment_status}  \n**Repo/PR:** ${deploymentRunRow.repo} #${deploymentRunRow.pr_number}  \n**Commit:** ${deploymentRunRow.commit_sha}  \n**Actor:** ${deploymentRunRow.actor}  \n**Gate:** PASS | approved=${deploymentRunRow.approved} | signal=${c.deploy_signal || 'n/a'}\n\n### Deployed content\n- Wazuh rules: ${deploymentRunRow.wazuh_rules_count}\n- Wazuh decoders: ${deploymentRunRow.wazuh_decoders_count}\n- Policy files: ${deploymentRunRow.policy_files_count}\n- Policy bundle: ${policyBundleRow.policy_bundle_version}${policyBundleRow.policy_bundle_hash ? ` (${policyBundleRow.policy_bundle_hash})` : ''}\n\n### Deployment safety\n- Backup root: ${deploymentRunRow.backup_root || 'n/a'}\n- Wazuh backup: ${deploymentRunRow.wazuh_backup_path || 'n/a'}\n- Policy backup: ${deploymentRunRow.policy_backup_path || 'n/a'}\n- Staging dir: ${deploymentRunRow.staging_dir || 'n/a'}\n- Rollback performed: ${deploymentRunRow.rollback_performed}${deploymentRunRow.rollback_reason ? ` - ${deploymentRunRow.rollback_reason}` : ''}\n\n### Stage results\n${stageMd}\n\n### Gate labels\n- Required: ${deploymentRunRow.required_labels_csv}\n- Observed: ${deploymentRunRow.observed_labels_csv}\n\n${deploymentRunRow.error ? `### Error\n\`${deploymentRunRow.error}\`\n` : ''}`;
const slackText = `*Flow B2 Controlled Deployment ${decision.toUpperCase()}*\n*Status:* ${deploymentRunRow.deployment_status} | *Repo/PR:* ${deploymentRunRow.repo} #${deploymentRunRow.pr_number}\n*Commit:* ${deploymentRunRow.commit_sha}\n*Stages:* ${passed}/${stageRows.length || (passed + failed)} passed, ${failed} failed\n*Backup:* ${deploymentRunRow.wazuh_backup_path || 'n/a'} | ${deploymentRunRow.policy_backup_path || 'n/a'}\n*Rollback:* ${deploymentRunRow.rollback_performed}\n*Error:* ${deploymentRunRow.error || 'none'}`;
return [{ json: { ...$json, github_body: githubBody, slack_text: slackText, deployment_run_row: deploymentRunRow, policy_bundle_deployment_row: policyBundleRow, labels } }];

const base = $('Code_Build_B2_Deployment_Report').first().json;
let github = {};
try { github = $('HTTP_GitHub_Post_B2_Deployment_Comment').first().json || {}; } catch (e) { github = {}; }
const slack = $json || {};
const slackErr = slack.error?.message || slack.error?.description || slack.error || '';
const githubErr = github.error?.message || github.error?.description || github.error || '';
const githubPosted = Boolean(github.id || github.url || github.html_url) && !githubErr;
const slackNotified = Boolean(slack.ok === true || slack.ts || slack.message?.ts) && !slackErr;
return [{ json: {
  ...base,
  github_response: github,
  slack_response: slack,
  deployment_run_row: {
    ...base.deployment_run_row,
    github_comment_posted: githubPosted,
    slack_notified: slackNotified,
    notes: [base.deployment_run_row?.notes || '', base.deployment_run_row?.commit_sha ? `commit_sha=${base.deployment_run_row.commit_sha}` : '', githubPosted ? `github_comment=${github.html_url || github.url || ''}` : '', slackNotified ? `slack_ts=${slack.ts || slack.message?.ts || ''}` : ''].filter(Boolean).join(' | '),
    error: [base.deployment_run_row?.error || '', githubErr ? `github=${githubErr}` : '', slackErr ? `slack=${slackErr}` : ''].filter(Boolean).join(' | ')
  },
  policy_bundle_deployment_row: {
    ...base.policy_bundle_deployment_row,
    deployment_status: base.deployment_run_row?.deployment_status || base.policy_bundle_deployment_row?.deployment_status || 'unknown',
    error: [base.policy_bundle_deployment_row?.error || '', githubErr ? `github=${githubErr}` : '', slackErr ? `slack=${slackErr}` : ''].filter(Boolean).join(' | ')
  }
}}];

const c = $json.deploy_context || {};
if (!c.deploy_signal_ok && String(c.deploy_signal || '') === 'ignore') {
  return [];
}
const now = new Date().toISOString();
const missing = $json.missing_labels || [];
const reason = $json.gate_reason || `blocked ${missing.length ? `missing=${missing.join(',')}` : 'deploy gate not satisfied'}`;
const row = {
  deployment_run_id: c.deployment_id || `blocked-${Date.now()}`,
  timestamp: now,
  deployment_mode: c.deploy_mode || 'execute',
  deployment_status: 'blocked',
  repo: c.repo || '',
  pr_number: Number(c.pr_number || 0),
  commit_sha: c.commit_sha || '',
  actor: c.actor || '',
  approved: Boolean(c.approved),
  gate_passed: false,
  required_labels_csv: (c.required_labels || []).join(','),
  observed_labels_csv: (c.labels || []).join(','),
  backup_root: '',
  wazuh_backup_path: '',
  policy_backup_path: '',
  staging_dir: '',
  wazuh_rules_count: 0,
  wazuh_decoders_count: 0,
  policy_files_count: 0,
  predeploy_status: 'blocked_before_predeploy',
  postdeploy_status: 'not_started',
  rollback_performed: false,
  rollback_reason: '',
  slack_notified: false,
  github_comment_posted: false,
  error: reason,
  stage_results_json: JSON.stringify([{stage_name:'deploy_gate', status:'blocked', passed:false, summary:reason}]),
  notes: `Flow B2 gate blocked before deployment; signal=${c.deploy_signal}; approval=${c.approval_status || 'missing'}`
};
const githubBody = `## Flow B2 Controlled Wazuh + AI Security Policy Deployment\n\n**Decision:** BLOCKED  \n**Deployment status:** blocked  \n**Repo/PR:** ${row.repo} #${row.pr_number}  \n**Commit:** ${row.commit_sha}  \n**Actor:** ${row.actor}  \n**Signal:** ${c.deploy_signal || 'n/a'}  \n**Gate:** FAIL | approved=${row.approved}\n\n### Block reason\n${reason}\n\n### Required gate\n- Required labels: ${row.required_labels_csv}\n- Observed labels: ${row.observed_labels_csv}\n- Approval required: true\n- Valid deploy signal required: true\n\n### Safety result\nNo Wazuh files were staged, activated, or restarted. Deployment stopped before touching the Wazuh manager.`;
const slackText = `*Flow B2 Controlled Deployment BLOCKED*\n*Repo/PR:* ${row.repo} #${row.pr_number}\n*Commit:* ${row.commit_sha}\n*Signal:* ${c.deploy_signal || 'n/a'}\n*Reason:* ${reason}\n*Observed labels:* ${row.observed_labels_csv}\n*Required labels:* ${row.required_labels_csv}\n*Safety:* no Wazuh changes applied`;
return [{ json: { ...$json, github_body: githubBody, slack_text: slackText, deployment_run_row: row } }];

const e = $('Code_Extract_B2_GitHub_Event').first().json;
const pr = $json || {};
const labels = Array.isArray(pr.labels) ? pr.labels.map(x => x.name).filter(Boolean) : [];
const reviewApproved = String(e.review_state || '').toLowerCase() === 'approved';
const labelApproved = labels.includes('approved') || labels.includes('review-approved');
const approved = reviewApproved || labelApproved;
const signalOk = ['label_ready_to_deploy','manual_deploy_comment','review_approved','merge_to_main'].includes(e.deploy_signal);
const ctx = {
  event_type: 'flow_b2_github_deploy_signal',
  deployment_id: `flow-b2-${e.repo.replace('/','-')}-pr-${e.pr_number}-${Date.now()}`,
  repo: e.repo,
  repo_owner: e.owner,
  repo_name: e.repo_name,
  pr_number: Number(e.pr_number || 0),
  issue_number: Number(e.issue_number || e.pr_number || 0),
  commit_sha: pr.head?.sha || e.head_sha || 'unknown',
  base_sha: pr.base?.sha || e.base_sha || '',
  base_ref: pr.base?.ref || e.base_ref || 'main',
  actor: e.actor,
  approved,
  approval_status: approved ? 'approved' : 'missing',
  deploy_environment: 'lab',
  deploy_mode: 'execute',
  deploy_signal: e.deploy_signal,
  deploy_signal_ok: signalOk,
  labels,
  required_labels: ['ai-security-ci-pass','detection-ci-pass','mcp-policy-pass','rag-policy-pass','agentic-policy-pass','ready-to-deploy'],
  notes: `event=${e.event_name}; action=${e.event_action}; signal=${e.deploy_signal}`
};
return [{ json: { received_at: new Date().toISOString(), deploy_context: ctx, deploy_context_json: JSON.stringify(ctx), deploy_context_b64: Buffer.from(JSON.stringify(ctx), 'utf8').toString('base64') } }];

const base = $('Code_Build_B2_Blocked_Report').first().json;
let github = {};
try { github = $('HTTP_GitHub_Post_B2_Blocked_Comment').first().json || {}; } catch (e) { github = {}; }
const slack = $json || {};
const slackErr = slack.error?.message || slack.error?.description || slack.error || '';
const githubErr = github.error?.message || github.error?.description || github.error || '';
const githubPosted = Boolean(github.id || github.url || github.html_url) && !githubErr;
const slackNotified = Boolean(slack.ok === true || slack.ts || slack.message?.ts) && !slackErr;
return [{ json: {
  ...base,
  github_response: github,
  slack_response: slack,
  deployment_run_row: {
    ...base.deployment_run_row,
    github_comment_posted: githubPosted,
    slack_notified: slackNotified,
    notes: [base.deployment_run_row?.notes || '', base.deployment_run_row?.commit_sha ? `commit_sha=${base.deployment_run_row.commit_sha}` : '', githubPosted ? `github_comment=${github.html_url || github.url || ''}` : '', slackNotified ? `slack_ts=${slack.ts || slack.message?.ts || ''}` : ''].filter(Boolean).join(' | '),
    error: [base.deployment_run_row?.error || '', githubErr ? `github=${githubErr}` : '', slackErr ? `slack=${slackErr}` : ''].filter(Boolean).join(' | ')
  }
}}];
